import random, math
random.seed(0)
def gen(n, outlier_frac, outlier_scale):
    x=[]
    for _ in range(n):
        if random.random()<outlier_frac: x.append(random.gauss(0,outlier_scale))
        else: x.append(random.gauss(0,1.0))
    return x
def sym_mse(x,b,alpha):
    L=2**(b-1)-1; T=alpha*max(abs(v) for v in x); s=T/L
    e=0.0
